import math

def ratio(term, n=60):
    return abs(term(n + 1) / term(n))

print("sum 10^n / n!  :", round(ratio(lambda n: 10 ** n / math.factorial(n)), 4), "< 1: converges")
print("sum n! / n^n   :", round(ratio(lambda n: math.factorial(n) / n ** n), 4), "< 1: converges (tends to 1/e)")
print("sum 1 / n^2    :", round(ratio(lambda n: 1 / n ** 2), 4), "-> 1: inconclusive, use the p-test")

import math

def series_exp(x, terms):
    return sum(x ** n / math.factorial(n) for n in range(terms))

for terms in (2, 4, 8, 12):
    print(terms, round(series_exp(2.0, terms), 6), "vs", round(math.exp(2.0), 6))

# 1/(1 + x^2) = 1 - x^2 + x^4 - ...   smooth on the real line, but the series only works for |x| < 1
def partial(x, n):
    return sum((-1) ** k * x ** (2 * k) for k in range(n))

for x in (0.5, 0.9, 1.1):
    print(x, [round(partial(x, n), 3) for n in (5, 10, 20, 40)], "target", round(1 / (1 + x * x), 3))

import math

def taylor_sin(x, terms):
    return sum((-1) ** k * x ** (2 * k + 1) / math.factorial(2 * k + 1) for k in range(terms))

x = 2.0
for terms in (1, 2, 3, 5, 8):
    print(terms, round(taylor_sin(x, terms), 8), "error", f"{abs(taylor_sin(x, terms) - math.sin(x)):.2e}")

import math

def square_wave(x, harmonics):
    return 4 / math.pi * sum(math.sin((2 * k + 1) * x) / (2 * k + 1) for k in range(harmonics))

for harmonics in (1, 3, 10, 50):
    print(harmonics, [round(square_wave(x, harmonics), 3) for x in (0.5, 1.0, 1.5, 2.0)])   # approaches 1.0
print("Gibbs overshoot near the jump:", round(max(square_wave(i * 0.001, 50) for i in range(1, 300)), 3))
